//! SigmaOS kernel ELF entry — `_start` for Multiboot2.
//!
//! The bootloader places a pointer to the MB2 info struct in %rbx.
//! This binary is linked at physical 0x100000 by linker.ld; the
//! `.multiboot2` section (generated by build.rs) sits in the first
//! page so the bootloader finds the header.

#![no_std]
#![no_main]

extern crate alloc;

use alloc::string::ToString;
use alloc::vec;
use alloc::vec::Vec;
extern crate sigma_kernel as kernel;

#[allow(unsafe_code)]
mod arch;

core::arch::global_asm!(include_str!("pvh.asm"), options(att_syntax));

/// Multiboot2 header generated by build.rs via sigma-bootloader.
/// MB2 header must sit in the first 32 KiB of the loaded image.
#[used]
#[link_section = ".multiboot2"]
static MB2_HEADER: [u8; MB2_HEADER_LEN] =
    *include_bytes!(concat!(env!("OUT_DIR"), "/mb2header.bin"));

const MB2_HEADER_LEN: usize = 512;

/// Kernel entry point.
///
/// MB2: %eax = 0, %rbx = info struct pointer.
/// MB1: %eax = 0x2BADB002, %ebx = info struct pointer.
#[no_mangle]
pub extern "C" fn _start() -> ! {
    let (eax, info_ptr) = arch::boot_regs();
    arch::init();
    arch::log(&alloc::format!(
        "sigma-kernel: entry eax={:#x} info={:#x}\n",
        eax,
        info_ptr
    ));

    if eax == kernel::boot::MB1_MAGIC_EAX {
        // MB1: fixed 48-byte header + separate mmap table + cmdline.
        // SAFETY: %ebx points to a valid MB1 info struct.
        let hdr_bytes = unsafe { core::slice::from_raw_parts(info_ptr as *const u8, 48) };
        let hdr = match kernel::boot::Mb1InfoHeader::parse(hdr_bytes) {
            Ok(h) => h,
            Err(e) => {
                arch::log(&alloc::format!("sigma-kernel: mb1 header parse {:?}\n", e));
                loop {
                    arch::halt();
                }
            }
        };
        // Copy the mmap table out of low memory.
        let mmap = unsafe {
            core::slice::from_raw_parts(hdr.mmap_ptr as *const u8, hdr.mmap_len as usize)
        };
        // cmdline is a NUL-terminated string at cmdline_ptr (may be 0).
        let cmdline = if hdr.cmdline_ptr != 0 {
            let p = hdr.cmdline_ptr as *const u8;
            let mut len = 0usize;
            // SAFETY: cmdline_ptr points to a NUL-terminated string.
            unsafe {
                while *p.add(len) != 0 && len < 4096 {
                    len += 1;
                }
                core::str::from_utf8_unchecked(core::slice::from_raw_parts(p, len)).to_string()
            }
            .into()
        } else {
            None
        };
        match kernel::boot::parse_mb1(&hdr_bytes.to_vec(), mmap, cmdline) {
            Ok(bi) => boot_ok(&bi),
            Err(e) => boot_fail(&e),
        }
    } else {
        // MB2: %rbx points to info struct; first u32 = total size.
        // SAFETY: %rbx points to a valid MB2 info struct.
        let total = unsafe { (info_ptr as *const u32).read_unaligned() } as usize;
        let info = unsafe { core::slice::from_raw_parts(info_ptr as *const u8, total) };
        match kernel::boot::parse_mb2(info) {
            Ok(bi) => boot_ok(&bi),
            Err(e) => boot_fail(&e),
        }
    }
}

fn boot_ok(bi: &kernel::boot::BootInfo) -> ! {
    arch::log(&alloc::format!(
        "sigma-kernel: {} memory regions, fb={} cmdline={:?}\n",
        bi.mem_regions.len(),
        bi.framebuffer.is_some(),
        bi.cmdline
    ));

    // VGA text console + serial mirror.
    unsafe {
        CON = Some(kernel::console::TextConsole::new(
            arch::VgaBuf,
            kernel::console::attr::make(
                kernel::console::attr::LIGHT_GREEN,
                kernel::console::attr::BLACK,
            ),
        ));
    }
    #[allow(static_mut_refs)]
    let con = unsafe { sys_con() };
    con.println("SigmaOS kernel — PVH boot");
    con.println(&alloc::format!(
        "mem regions: {}   modules: {}",
        bi.mem_regions.len(),
        bi.modules.len()
    ));

    // Mount the initramfs module — scan modules for the cpio magic.
    let mut vfs = kernel::vfs::Vfs::new();
    let mut initrd: Option<&[u8]> = None;
    for &(paddr, size) in &bi.modules {
        // SAFETY: module paddr/size come from hvm_start_info; identity-mapped.
        let bytes = unsafe { core::slice::from_raw_parts(paddr as *const u8, size as usize) };
        if bytes.len() >= 6 && &bytes[..6] == b"070701" {
            initrd = Some(bytes);
            break;
        }
    }
    if let Some(bytes) = initrd {
        match vfs.load_cpio_newc(bytes) {
            Ok(()) => {
                arch::log(&alloc::format!(
                    "sigma-kernel: initramfs mounted ({} nodes)\n",
                    vfs.len()
                ));
                con.println(&alloc::format!("initramfs: {} nodes", vfs.len()));
                if let Some(list) = vfs.list("/") {
                    for name in list {
                        con.println(&alloc::format!("  /{}", name));
                    }
                }
                if let Some(init) = vfs.read("/init") {
                    arch::log(&alloc::format!(
                        "sigma-kernel: /init present ({} bytes)\n",
                        init.len()
                    ));
                    con.println(&alloc::format!("/init: {} bytes", init.len()));
                    // Probe ELF header — reports entry + load segments.
                    match kernel::elf::parse_header(init)
                        .and_then(|h| kernel::elf::load_segments(init, &h).map(|s| (h, s)))
                    {
                        Ok((h, segs)) => {
                            let (lo, hi) = kernel::elf::image_span(&segs);
                            arch::log(&alloc::format!(
                                "sigma-kernel: /init ELF entry={:#x} span={:#x}..{:#x} segs={}\n",
                                h.entry,
                                lo,
                                hi,
                                segs.len()
                            ));
                            con.println(&alloc::format!(
                                "/init ELF: entry {:#x}, {} segs",
                                h.entry,
                                segs.len()
                            ));
                        }
                        Err(e) => {
                            arch::log(&alloc::format!("sigma-kernel: /init not ELF: {:?}\n", e));
                            con.println("/init: not a loadable ELF");
                        }
                    }
                }
            }
            Err(e) => {
                arch::log(&alloc::format!("sigma-kernel: initramfs error {:?}\n", e));
                con.println("initramfs: parse error");
            }
        }
        // publish for the syscall layer
        unsafe { VFS = Some(vfs) };
    } else {
        arch::log("sigma-kernel: no initramfs module\n");
        con.println("no initramfs module");
    }

    // Run /init in ring 3 if present.
    if let Some(init) = unsafe { sys_vfs() }.read("/init") {
        run_init(init, bi, con);
    }

    // PS/2 keyboard + interactive echo.
    let mut kbd = kernel::ps2::Keyboard::new(arch::Ps2Hw);
    con.println("type on keyboard (echo to serial+vga)...");
    let mut line = alloc::string::String::new();
    loop {
        kbd.poll();
        for key in kbd.drain() {
            match key {
                kernel::ps2::Key::Char(c) => {
                    con.put_byte(c);
                    arch::log(core::str::from_utf8(&[c]).unwrap_or(""));
                    line.push(c as char);
                }
                kernel::ps2::Key::Enter => {
                    con.newline_pub();
                    arch::log("\n");
                    con.println(&alloc::format!("got: {}", line));
                    line.clear();
                }
                kernel::ps2::Key::Backspace => {
                    line.pop();
                    con.backspace_pub();
                }
                _ => {}
            }
        }
        arch::halt();
    }
}

/// PVH entry — called from the 32→64-bit stub with the physical
/// address of hvm_start_info in %rdi.
#[no_mangle]
pub extern "C" fn pvh_kernel_entry(info_ptr: u64) -> ! {
    arch::init();
    arch::log("sigma-kernel: pvh entry\n");

    // SAFETY: %rdi holds a valid hvm_start_info physical address per
    // the PVH boot ABI; all fields below 4 GiB are directly mapped.
    let read_u32 =
        |off: usize| -> u32 { unsafe { ((info_ptr + off as u64) as *const u32).read_unaligned() } };
    let read_u64 =
        |off: usize| -> u64 { unsafe { ((info_ptr + off as u64) as *const u64).read_unaligned() } };

    if read_u32(0) != kernel::boot::PVH_MAGIC {
        arch::log("sigma-kernel: bad pvh magic\n");
        loop {
            arch::halt();
        }
    }
    let version = read_u32(4);
    let nr_modules = read_u32(12);
    let modlist_paddr = read_u64(16);
    let cmdline_paddr = read_u64(24);
    let memmap_paddr = read_u64(40);
    let memmap_entries = read_u32(48);
    let _ = version;

    // hvm_start_info fixed part: copy the 56-byte header.
    // SAFETY: info struct is at least 56 bytes per spec.
    let info_bytes = unsafe { core::slice::from_raw_parts(info_ptr as *const u8, 56) };

    // Memory map entries (24 bytes each) -> owned Vec.
    let memmap_bytes: alloc::vec::Vec<u8> = if memmap_entries > 0 && memmap_paddr != 0 {
        let len = memmap_entries as usize * 24;
        // SAFETY: memmap_paddr points to memmap_entries * 24 bytes.
        unsafe { core::slice::from_raw_parts(memmap_paddr as *const u8, len) }.to_vec()
    } else {
        alloc::vec::Vec::new()
    };

    // Modules (initrd etc.): 32-byte hvm_modlist_entry each.
    let mut modules = alloc::vec::Vec::new();
    for i in 0..nr_modules as usize {
        let base = modlist_paddr + (i * 32) as u64;
        // SAFETY: modlist has nr_modules entries of 32 bytes.
        let paddr = unsafe { (base as *const u64).read_unaligned() };
        let size = unsafe { ((base + 8) as *const u64).read_unaligned() };
        modules.push((paddr, size));
    }

    // Command line: NUL-terminated at cmdline_paddr (0 = absent).
    let cmdline = if cmdline_paddr != 0 {
        let p = cmdline_paddr as *const u8;
        let mut len = 0usize;
        // SAFETY: cmdline_paddr points to a NUL-terminated string.
        unsafe {
            while *p.add(len) != 0 && len < 4096 {
                len += 1;
            }
        }
        // SAFETY: i < len bytes are valid at p.
        let bytes = unsafe { core::slice::from_raw_parts(p, len) };
        Some(alloc::string::String::from_utf8_lossy(bytes).into_owned())
    } else {
        None
    };

    match kernel::boot::parse_pvh(&info_bytes.to_vec(), &memmap_bytes, modules, cmdline) {
        Ok(bi) => boot_ok(&bi),
        Err(e) => boot_fail(&e),
    }
}

fn boot_fail(e: &kernel::KernelError) -> ! {
    arch::log(&alloc::format!("sigma-kernel: boot info error {:?}\n", e));
    loop {
        arch::halt();
    }
}

/// Bump allocator over a static heap region — replaced by the frame
/// allocator once paging/mm is initialized.
#[allow(unsafe_code)]
mod bump {
    use core::alloc::{GlobalAlloc, Layout};

    const HEAP_SIZE: usize = 4 * 1024 * 1024;
    static mut HEAP: [u8; HEAP_SIZE] = [0; HEAP_SIZE];
    static mut NEXT: usize = 0;

    pub struct Bump;

    unsafe impl GlobalAlloc for Bump {
        unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
            let size = layout.size();
            // SAFETY: single-CPU boot path, allocation is bump-only.
            unsafe {
                let cur = NEXT;
                // Always hand out 16-byte-aligned pointers: callers may
                // use aligned SSE copies regardless of layout.align().
                let aligned = (cur + 15) & !15;
                let end = aligned + size;
                if end > HEAP_SIZE {
                    return core::ptr::null_mut();
                }
                NEXT = end;
                // SAFETY: `aligned + size <= HEAP_SIZE` was checked above,
                // so the returned pointer stays inside the static heap.
                core::ptr::addr_of_mut!(HEAP).cast::<u8>().add(aligned)
            }
        }
        unsafe fn dealloc(&self, _ptr: *mut u8, _layout: Layout) {}
    }
}

#[global_allocator]
static GLOBAL: bump::Bump = bump::Bump;

/// Panic handler — log and halt.
#[panic_handler]
fn panic(info: &core::panic::PanicInfo) -> ! {
    arch::log("sigma-kernel: PANIC\n");
    if let Some(loc) = info.location() {
        arch::log(&alloc::format!("  at {}:{}\n", loc.file(), loc.line()));
    }
    loop {
        arch::halt();
    }
}

/// Global VFS — populated at boot, shared with the syscall layer.
static mut VFS: Option<kernel::vfs::Vfs> = None;

/// User-process memory state for BRK/MMAP syscalls.
pub static mut USER_PML4: u64 = 0;
pub static mut USER_ALLOC: Option<kernel::mm::FrameAllocator> = None;
pub static mut USER_BRK: u64 = 0x10000000; // 256 MiB, above image+stack

/// Global VGA console for syscall output.
static mut CON: Option<kernel::console::TextConsole<arch::VgaBuf>> = None;

/// Borrow the console (syscall path).
#[allow(static_mut_refs)]
pub unsafe fn sys_con() -> &'static mut kernel::console::TextConsole<arch::VgaBuf> {
    unsafe { CON.as_mut().unwrap() }
}

/// Borrow the mounted VFS (syscall path).
#[allow(static_mut_refs)]
pub unsafe fn sys_vfs() -> &'static kernel::vfs::Vfs {
    unsafe { VFS.as_ref().unwrap() }
}

/* ---- ring-3 user entry + process table ---- */

extern "C" {
    fn enter_user(entry: u64, rsp: u64, cr3: u64) -> !;
    static mut cur_ctx: u64;
    static mut next_ctx: u64;
    static mut switch_req: u64;
}

/// Max concurrent user processes (preemptive round-robin via timer IRQ).
pub const NPROCS: usize = 4;

/// ctx slot indices — must match pvh.asm syscall_entry layout.
mod cx {
    pub const RAX: usize = 0;
    pub const RIP: usize = 1;
    pub const RDX: usize = 2;
    pub const RSI: usize = 3;
    pub const RDI: usize = 4;
    pub const R8: usize = 5;
    pub const R9: usize = 6;
    pub const R10: usize = 7;
    pub const RBX: usize = 8;
    pub const RBP: usize = 9;
    pub const R12: usize = 10;
    pub const R13: usize = 11;
    pub const R14: usize = 12;
    pub const R15: usize = 13;
    pub const SP: usize = 14;
    pub const FL: usize = 15;
    pub const CR3: usize = 16;
    /// Slots 17/18 hold rcx/r11 saved by the IRQ preemption path
    /// (syscall ctx derives them from rip/rflags instead).
    pub const RCX: usize = 17;
    pub const R11: usize = 18;
}

/// Per-process saved user context (19 u64s; slots 0-16 by syscall_entry,
/// 17/18 rcx/r11 by the IRQ preemption path).
static mut CTX: [[u64; 19]; NPROCS] = [[0; 19]; NPROCS];

/// Process table entry — the Linux task_struct analogue, minimal.
#[derive(Clone, Copy)]
pub struct ProcSlot {
    pub used: bool,
    pub exited: bool,
    pub sleeping: bool, // Skipped by sched_tick until woken
    pub wait_pid: u64,  // Pid this proc is blocked waiting on (0 = none)
    pub reaped: bool,   // Exit status already delivered to a waiter
    pub pid: u64,
    pub parent: i64,
    pub exit_code: u64,
    pub pml4: u64,
    pub brk: u64,
    pub frame_count: u16, // Number of user frames allocated (for teardown)
    pub fds: [FdEnt; 8],  // Per-process file descriptor table
}

const MAX_FDS: usize = 8;
const MAX_PIPES: usize = 4;
const PIPE_BUF_SIZE: usize = 4096;

/// Fd kinds: regular file, pipe read end, pipe write end.
pub const FD_FILE: u8 = 0;
pub const FD_PIPE_READ: u8 = 1;
pub const FD_PIPE_WRITE: u8 = 2;

/// A kernel pipe: fixed-size FIFO buffer shared by two fds.
/// head = read index, tail = write index, count = bytes buffered.
#[derive(Clone, Copy)]
pub struct Pipe {
    pub used: bool,
    pub buf: [u8; PIPE_BUF_SIZE],
    pub head: usize,
    pub tail: usize,
    pub count: usize,
}

impl Pipe {
    const fn new() -> Self {
        Self {
            used: false,
            buf: [0; PIPE_BUF_SIZE],
            head: 0,
            tail: 0,
            count: 0,
        }
    }
}

#[derive(Clone, Copy)]
pub struct FdEnt {
    pub used: bool,
    pub kind: u8,
    pub pipe_id: u8,
    pub path: [u8; 64],
    pub len: u32,
    pub off: u64,
}

pub static mut PIPES: [Pipe; MAX_PIPES] = [Pipe::new(), Pipe::new(), Pipe::new(), Pipe::new()];

pub static mut PROCS: [ProcSlot; NPROCS] = [ProcSlot {
    used: false,
    exited: false,
    sleeping: false,
    wait_pid: 0,
    reaped: false,
    pid: 0,
    parent: -1,
    exit_code: 0,
    pml4: 0,
    brk: 0,
    frame_count: 0,
    fds: [FdEnt {
        used: false,
        kind: FD_FILE,
        pipe_id: 0,
        path: [0; 64],
        len: 0,
        off: 0,
    }; 8],
}; NPROCS];
static mut NEXT_PID: u64 = 1;
/// Index of the currently running process.
pub static mut CUR_PROC: usize = 0;

/// Switch the running process: saves the current globals into its
/// slot, loads the target's, and asks asm to load next_ctx.
/// (Linux `context_switch` + `__switch_to` analogue.)
unsafe fn switch_to(idx: usize) {
    let cur = CUR_PROC;
    PROCS[cur].pml4 = USER_PML4;
    PROCS[cur].brk = USER_BRK;
    CUR_PROC = idx;
    USER_PML4 = PROCS[idx].pml4;
    USER_BRK = PROCS[idx].brk;
    cur_ctx = CTX[idx].as_mut_ptr() as u64;
    next_ctx = cur_ctx;
    switch_req = 1;
}

/// Get the current process's fd table (for arch.rs helpers).
unsafe fn current_fds() -> &'static mut [FdEnt; MAX_FDS] {
    &mut PROCS[CUR_PROC].fds
}

/// Allocate a new fd slot in the current process's fd table.
unsafe fn fd_alloc() -> Option<usize> {
    current_fds().iter().position(|f| !f.used)
}

/// Get an fd entry from the current process's fd table.
unsafe fn fd_get(fd: u64) -> Option<&'static mut FdEnt> {
    let i = fd.checked_sub(3)? as usize;
    if i < MAX_FDS && current_fds()[i].used {
        Some(&mut current_fds()[i])
    } else {
        None
    }
}

/// Find the next runnable process (not exited, not sleeping) starting
/// from `from` (exclusive). Returns None if no runnable process exists.
/// (Linux `pick_next_task` analogue.)
unsafe fn next_runnable(from: usize) -> Option<usize> {
    for off in 1..=NPROCS {
        let i = (from + off) % NPROCS;
        if PROCS[i].used && !PROCS[i].exited && !PROCS[i].sleeping {
            return Some(i);
        }
    }
    None
}

/// Timer-tick scheduler — called from `irq_common` on timer IRQs after
/// the interrupted user ctx has been saved into the current proc's slot.
/// Picks the next runnable process round-robin, swaps the per-process
/// globals (pml4/brk), and points `cur_ctx` at the target ctx; the asm
/// then loads that ctx and `iretq`s into it. With a single runnable
/// process it returns the same ctx — a harmless self-reschedule.
/// (Linux `scheduler_tick` + `context_switch` analogue.)
#[no_mangle]
pub extern "C" fn sched_tick() {
    // SAFETY: single-CPU, IRQ-time context; PROCS/CTX are ours.
    unsafe {
        for off in 1..=NPROCS {
            let i = (CUR_PROC + off) % NPROCS;
            if PROCS[i].used && !PROCS[i].exited && !PROCS[i].sleeping {
                PROCS[CUR_PROC].pml4 = USER_PML4;
                PROCS[CUR_PROC].brk = USER_BRK;
                CUR_PROC = i;
                USER_PML4 = PROCS[i].pml4;
                USER_BRK = PROCS[i].brk;
                cur_ctx = CTX[i].as_mut_ptr() as u64;
                return;
            }
        }
    }
}

/// Syscall trap entry — called from asm `syscall_entry` with the
/// full user context saved in the current ctx. Handles process
/// syscalls (SPAWN/WAIT/EXIT) directly; everything else goes through
/// the kernel ABI dispatch.
#[no_mangle]
pub extern "C" fn syscall_trap() -> i64 {
    // SAFETY: ctx written by syscall_entry asm before the call.
    unsafe {
        switch_req = 0;
        let ctx = cur_ctx as *mut u64;
        let nr = *ctx;
        // arg regs rdi,rsi,rdx,r10,r8,r9 -> ctx slots 4,3,2,7,5,6
        let args = [
            *ctx.add(cx::RDI),
            *ctx.add(cx::RSI),
            *ctx.add(cx::RDX),
            *ctx.add(cx::R10),
            *ctx.add(cx::R8),
            *ctx.add(cx::R9),
        ];
        use kernel::syscall::nr;
        match nr {
            nr::SPAWN => sys_spawn(args[0], args[1], args[2]),
            nr::WAIT => sys_wait(args[0]),
            nr::EXIT => sys_exit(args[0]),
            nr::MEMINFO => sys_meminfo(args[0], args[1]),
            nr::PROCINFO => sys_procinfo(args[0], args[1]),
            _ => {
                let mut svc = arch::TrapSvc;
                kernel::syscall::dispatch(nr, &args, &mut svc)
            }
        }
    }
}

/// Build the initial stack image {argc, argv[], NULL, envp NULL,
/// strings...} at the top of the child's stack and return the initial
/// user rsp pointing at argc. `strings[0]` is argv[0] (the path).
/// Writes through the phys identity map — the child CR3 isn't active.
unsafe fn setup_argv(
    img: &kernel::process::UserImage,
    stack_lo: u64,
    strings: &[alloc::vec::Vec<u8>],
) -> Result<u64, i64> {
    let n = strings.len();
    if n == 0 || n > 16 {
        return Err(-22);
    }
    let header = 8 + (n as u64 + 1) * 8 + 8; // argc + argv + NULL + envp NULL
    let str_total: u64 = strings.iter().map(|s| s.len() as u64 + 1).sum();
    let block_len = (header + str_total + 15) & !15;
    if block_len > img.stack_pages * 4096 {
        return Err(-12);
    }
    let start_va = kernel::process::USER_STACK_TOP - block_len;
    let mut block = alloc::vec::Vec::with_capacity(block_len as usize);
    // placeholder header; pointers patched after layout is known
    let argc_pos = block.len();
    block.extend_from_slice(&(n as u64).to_le_bytes());
    for _ in 0..n + 2 {
        block.extend_from_slice(&0u64.to_le_bytes());
    }
    let mut offs = alloc::vec::Vec::with_capacity(n);
    for s in strings {
        offs.push(block.len() as u64);
        block.extend_from_slice(s);
        block.push(0);
    }
    // patch argv pointers: string i lives at start_va + off
    for (i, off) in offs.iter().enumerate() {
        let va = start_va + off;
        let at = argc_pos + 8 + i * 8;
        block[at..at + 8].copy_from_slice(&va.to_le_bytes());
    }
    let dst_phys = img.stack_phys + (start_va - stack_lo);
    // SAFETY: dst_phys is inside the freshly allocated child stack.
    unsafe {
        core::ptr::copy_nonoverlapping(block.as_ptr(), dst_phys as *mut u8, block.len());
    }
    Ok(start_va)
}

/// Read the SPAWN args descriptor from parent memory (still the active
/// CR3): {u64 argc, argc x {u64 ptr, u64 len}}. Returns arg byte vecs.
unsafe fn read_spawn_args(args_ptr: u64) -> Result<alloc::vec::Vec<alloc::vec::Vec<u8>>, i64> {
    if args_ptr == 0 {
        return Ok(alloc::vec::Vec::new());
    }
    // SAFETY: args_ptr is a parent user VA mapped under the active CR3.
    let n = unsafe { *(args_ptr as *const u64) };
    if n > 15 {
        return Err(-22);
    }
    let mut out = alloc::vec::Vec::with_capacity(n as usize);
    for i in 0..n as usize {
        let d = args_ptr + 8 + (i * 16) as u64;
        let (p, l) = unsafe { (*(d as *const u64), *((d + 8) as *const u64)) };
        if l > 1024 {
            return Err(-22);
        }
        // SAFETY: p/l describe a parent user buffer.
        let bytes = unsafe { core::slice::from_raw_parts(p as *const u8, l as usize) };
        out.push(bytes.to_vec());
    }
    Ok(out)
}

/// SPAWN(path_ptr, path_len, args_ptr): load an ELF from the VFS into a fresh
/// address space and context-switch to it. Returns the child pid to
/// the *parent* (stored in its ctx before the switch).
unsafe fn sys_spawn(p_ptr: u64, p_len: u64, args_ptr: u64) -> i64 {
    if p_len == 0 || p_len > 64 {
        return -22;
    }
    // SAFETY: user path buffer mapped under the active (parent) CR3.
    let pb = unsafe { core::slice::from_raw_parts(p_ptr as *const u8, p_len as usize) };
    let path = match core::str::from_utf8(pb) {
        Ok(s) => s,
        Err(_) => return -14,
    };
    // argv strings: argv[0] = path, then caller args — all copied out of
    // parent memory now, before the CR3 switch.
    let mut arg_vecs = match unsafe { read_spawn_args(args_ptr) } {
        Ok(v) => v,
        Err(e) => return e,
    };
    let mut strings = alloc::vec::Vec::with_capacity(arg_vecs.len() + 1);
    strings.push(pb.to_vec());
    strings.append(&mut arg_vecs);
    let Some(elf) = (unsafe { sys_vfs() }).read(path) else {
        return -2; // ENOENT
    };
    let Some(slot) = (0..NPROCS).find(|&i| !PROCS[i].used) else {
        return -11; // EAGAIN: process table full
    };
    let alloc = match USER_ALLOC.as_mut() {
        Some(a) => a,
        None => return -12,
    };
    let img = match kernel::process::load_image(elf, alloc) {
        Ok(i) => i,
        Err(e) => {
            arch::log(alloc::format!("sys_spawn: load_image err {:?}\n", e).as_str());
            return -12;
        }
    };
    let mut pages = Vec::new();
    for s in &img.segments {
        for i in 0..s.frames {
            pages.push((s.vaddr + i * 4096, s.phys + i * 4096));
        }
    }
    let stack_lo = kernel::process::USER_STACK_TOP - img.stack_pages * 4096;
    for i in 0..img.stack_pages {
        pages.push((stack_lo + i * 4096, img.stack_phys + i * 4096));
    }
    let tables = match kernel::usermem::build_user_tables(
        &pages,
        kernel::process::USER_LOAD_BASE,
        alloc,
        &mut arch::IdentityPhysMem,
    ) {
        Ok(t) => t,
        Err(e) => {
            arch::log(alloc::format!("sys_spawn: tables err {:?}\n", e).as_str());
            return -12;
        }
    };
    for s in &img.segments {
        let len = (s.frames * 4096) as usize;
        // SAFETY: phys is a freshly allocated frame range we own.
        let dst = unsafe { core::slice::from_raw_parts_mut(s.phys as *mut u8, len) };
        if kernel::process::materialize_with_offset(elf, s.offset, s.filesz, s.memsz, s.delta, dst)
            .is_err()
        {
            arch::log("sys_spawn: materialize err\n");
            return -12;
        }
    }
    // Zero the user stack — freshly allocated frames are dirty.
    let st = unsafe {
        core::slice::from_raw_parts_mut(
            img.stack_phys as *mut u8,
            (img.stack_pages * 4096) as usize,
        )
    };
    st.fill(0);
    // argv block at the top of the child stack; rsp points at argc.
    let init_rsp = match unsafe { setup_argv(&img, stack_lo, &strings) } {
        Ok(r) => r,
        Err(e) => return e,
    };
    let pid = NEXT_PID;
    NEXT_PID += 1;
    // Child ctx: fresh register state, entry/rsp/rflags/cr3 set.
    let c = &mut CTX[slot];
    for v in c.iter_mut() {
        *v = 0;
    }
    c[cx::RIP] = img.entry;
    c[cx::SP] = init_rsp;
    c[cx::FL] = 0x202; // IF=1
    c[cx::CR3] = tables.cr3;
    let frame_count = (img.segments.iter().map(|s| s.frames).sum::<u64>() + img.stack_pages) as u16;
    PROCS[slot] = ProcSlot {
        used: true,
        exited: false,
        sleeping: false,
        wait_pid: 0,
        reaped: false,
        pid,
        parent: CUR_PROC as i64,
        exit_code: 0,
        pml4: tables.cr3,
        brk: USER_BRK,
        frame_count,
        fds: [FdEnt {
            used: false,
            kind: FD_FILE,
            pipe_id: 0,
            path: [0; 64],
            len: 0,
            off: 0,
        }; 8],
    };
    switch_to(slot);
    pid as i64
}

/// WAIT(pid): reap a child's exit status. Blocks until the child exits
/// (Linux `wait` analogue). Returns EAGAIN if no runnable process to switch to.
unsafe fn sys_wait(pid: u64) -> i64 {
    for i in 0..NPROCS {
        if PROCS[i].used && PROCS[i].pid == pid {
            if PROCS[i].parent != CUR_PROC as i64 {
                return -3; // ESRCH: not our child
            }
            if PROCS[i].exited {
                if PROCS[i].reaped {
                    return -10; // ECHILD: already reaped
                }
                PROCS[i].reaped = true;
                let status = PROCS[i].exit_code as i64;
                // Reclaim the child's resources (page tables, frames).
                reap_process(i);
                return status;
            }
            // Child still alive: block until it exits.
            let cur = CUR_PROC;
            match next_runnable(cur) {
                Some(j) => {
                    PROCS[cur].sleeping = true;
                    PROCS[cur].wait_pid = pid;
                    switch_to(j);
                    // When we wake, EXIT writes status into ctx.rax
                    return 0;
                }
                None => return -11, // EAGAIN: no runnable process
            }
        }
    }
    -3 // ESRCH
}

/// Reclaim a process's resources: free page tables and user frames.
/// Called by sys_wait after the child is reaped (Linux `release_task` analogue).
unsafe fn reap_process(idx: usize) {
    if !PROCS[idx].used {
        return;
    }
    let alloc = match USER_ALLOC.as_mut() {
        Some(a) => a,
        None => return,
    };
    // Free the user page tables (PML4 and all subordinate tables).
    let pml4 = PROCS[idx].pml4;
    if pml4 != 0 {
        kernel::usermem::free_user_tables(pml4, alloc, &mut arch::IdentityPhysMem);
    }
    // Note: user data frames are tracked but not yet freed because
    // we don't have a per-process frame list. This is a known gap.
    // For now, we just mark the slot as unused.
    PROCS[idx] = ProcSlot {
        used: false,
        exited: false,
        sleeping: false,
        wait_pid: 0,
        reaped: false,
        pid: 0,
        parent: -1,
        exit_code: 0,
        pml4: 0,
        brk: 0,
        frame_count: 0,
        fds: [FdEnt {
            used: false,
            kind: FD_FILE,
            pipe_id: 0,
            path: [0; 64],
            len: 0,
            off: 0,
        }; 8],
    };
}

/// MEMINFO(ptr, len): write {total_frames, free_frames} as two u64s
/// to the user buffer; len must be >= 16. Returns 0 or -errno.
unsafe fn sys_meminfo(ptr: u64, len: u64) -> i64 {
    if ptr == 0 || len < 16 {
        return -22;
    }
    let (total, free) = match USER_ALLOC.as_ref() {
        Some(a) => (a.total_frames(), a.free_frames()),
        None => return -12,
    };
    // SAFETY: caller validated ptr/len; user buf mapped under active CR3.
    unsafe {
        *(ptr as *mut u64) = total;
        *((ptr + 8) as *mut u64) = free;
    }
    0
}

/// PROCINFO(ptr, len): write NPROCS records of {pid, flags, exit_code}
/// (24 bytes each) to the user buffer. flags: bit0 exited, bit1
/// sleeping, bit2 reaped. Unused slots get pid=0. len >= NPROCS*24.
unsafe fn sys_procinfo(ptr: u64, len: u64) -> i64 {
    let need = (NPROCS * 24) as u64;
    if ptr == 0 || len < need {
        return -22;
    }
    // SAFETY: caller validated ptr/len; records written under active CR3.
    unsafe {
        for i in 0..NPROCS {
            let p = &PROCS[i];
            let rec = ptr + (i * 24) as u64;
            *(rec as *mut u64) = if p.used { p.pid } else { 0 };
            let mut flags = 0u64;
            if p.exited {
                flags |= 1;
            }
            if p.sleeping {
                flags |= 2;
            }
            if p.reaped {
                flags |= 4;
            }
            *((rec + 8) as *mut u64) = flags;
            *((rec + 16) as *mut u64) = p.exit_code;
        }
    }
    0
}

/// EXIT(code): mark the process exited, wake the waiting parent,
/// and switch to the next runnable process. Status is delivered via
/// ctx.rax to the waking parent (Linux `do_exit` + `wake_up` analogue).
unsafe fn sys_exit(code: u64) -> i64 {
    let cur = CUR_PROC;
    PROCS[cur].exited = true;
    PROCS[cur].exit_code = code;
    let parent = PROCS[cur].parent;
    if parent < 0 {
        arch::log("sigma-kernel: init exit\n");
        loop {
            arch::halt();
        }
    }
    let p = parent as usize;
    // Wake parent if it's sleeping on this child.
    if PROCS[p].sleeping && PROCS[p].wait_pid == PROCS[cur].pid {
        PROCS[p].sleeping = false;
        PROCS[p].wait_pid = 0;
        PROCS[cur].reaped = true;
        CTX[p][cx::RAX] = code as i64 as u64;
    }
    // Switch to next runnable process (prefer parent if it's awake).
    let target = next_runnable(cur).or_else(|| {
        if PROCS[p].used && !PROCS[p].exited && !PROCS[p].sleeping {
            Some(p)
        } else {
            None
        }
    });
    match target {
        Some(j) => {
            switch_to(j);
            0
        }
        None => {
            arch::log("sigma-kernel: no runnable process\n");
            loop {
                arch::halt();
            }
        }
    }
}

/// End of the loaded kernel image in physical memory. The PVH stub
/// loads kernel.elf at 0x100000, so its own ELF header is readable
/// through the identity map; the highest PT_LOAD vaddr+memsz is the
/// true extent — .bss pushes it well past 2 MiB.
fn kernel_image_end() -> u64 {
    // SAFETY: kernel ELF header sits at phys/virt 0x100000.
    unsafe {
        let base = 0x100000u64 as *const u8;
        let phoff = (base.add(0x20) as *const u64).read_unaligned();
        let phentsize = (base.add(0x36) as *const u16).read_unaligned() as usize;
        let phnum = (base.add(0x38) as *const u16).read_unaligned() as usize;
        let mut end = 0x100000u64 + 0x200000; // fallback: 3 MiB
        for i in 0..phnum {
            let ph = base.add(phoff as usize + i * phentsize);
            if (ph as *const u32).read_unaligned() != 1 {
                continue; // PT_LOAD only
            }
            let vaddr = (ph.add(16) as *const u64).read_unaligned();
            let memsz = (ph.add(40) as *const u64).read_unaligned();
            end = end.max(vaddr + memsz);
        }
        end
    }
}

/// Physical ranges the user allocator must never hand out:
/// the kernel image and every boot module (initramfs).
fn reserved_ranges(bi: &kernel::boot::BootInfo) -> Vec<(u64, u64)> {
    let kbase = 0x100000u64;
    let kend = kernel_image_end();
    let mut r = vec![
        (kbase, kend),
        // Legacy ISA hole: VGA memory + option ROM/BIOS area. Reads
        // return 0xff and writes are dropped — never allocator material.
        (0xa0000, 0x100000),
    ];
    for &(p, sz) in &bi.modules {
        r.push((p, p + sz));
    }
    r
}

fn usable_regions(bi: &kernel::boot::BootInfo) -> Vec<kernel::boot::MemRegion> {
    let reserved = reserved_ranges(bi);
    let mut out = Vec::new();
    'regions: for reg in &bi.mem_regions {
        if reg.mem_type != 1 {
            continue;
        }
        let rs = reg.start;
        let re = reg.start + reg.len;
        for &(lo, hi) in &reserved {
            if rs < hi && re > lo {
                // split around the reserved hole
                if rs < lo {
                    out.push(kernel::boot::MemRegion {
                        start: rs,
                        len: lo - rs,
                        mem_type: 1,
                    });
                }
                if hi < re {
                    out.push(kernel::boot::MemRegion {
                        start: hi,
                        len: re - hi,
                        mem_type: 1,
                    });
                }
                continue 'regions;
            }
        }
        out.push(*reg);
    }
    out
}

/// Load /init, build its page tables, materialize segments, and
/// enter ring 3. Diverges.
fn run_init(
    init: &[u8],
    bi: &kernel::boot::BootInfo,
    con: &mut kernel::console::TextConsole<arch::VgaBuf>,
) -> ! {
    let regions = usable_regions(bi);
    let mut alloc = match kernel::mm::FrameAllocator::new(&regions) {
        Ok(a) => a,
        Err(e) => {
            arch::log(&alloc::format!(
                "sigma-kernel: frame alloc failed {:?}\n",
                e
            ));
            con.println("frame allocator failed");
            loop {
                arch::halt()
            }
        }
    };
    let img = match kernel::process::load_image(init, &mut alloc) {
        Ok(i) => i,
        Err(e) => {
            arch::log(&alloc::format!("sigma-kernel: load_image failed {:?}\n", e));
            con.println("load_image failed");
            loop {
                arch::halt()
            }
        }
    };
    con.println(&alloc::format!(
        "/init loaded: entry {:#x}, {} segs",
        img.entry,
        img.segments.len()
    ));

    // Collect 4K user pages: segments + stack.
    let mut pages = Vec::new();
    for s in &img.segments {
        for i in 0..s.frames {
            pages.push((s.vaddr + i * 4096, s.phys + i * 4096));
        }
    }
    let stack_lo = kernel::process::USER_STACK_TOP - img.stack_pages * 4096;
    for i in 0..img.stack_pages {
        pages.push((stack_lo + i * 4096, img.stack_phys + i * 4096));
    }

    let tables = match kernel::usermem::build_user_tables(
        &pages,
        kernel::process::USER_LOAD_BASE,
        &mut alloc,
        &mut arch::IdentityPhysMem,
    ) {
        Ok(t) => t,
        Err(e) => {
            arch::log(&alloc::format!(
                "sigma-kernel: user tables failed {:?}\n",
                e
            ));
            con.println("user page tables failed");
            loop {
                arch::halt()
            }
        }
    };

    // Materialize segment bytes into the allocated frames.
    for s in &img.segments {
        let len = (s.frames * 4096) as usize;
        // SAFETY: phys is a freshly allocated frame range we own.
        let dst = unsafe { core::slice::from_raw_parts_mut(s.phys as *mut u8, len) };
        if let Err(e) = kernel::process::materialize_with_offset(
            init, s.offset, s.filesz, s.memsz, s.delta, dst,
        ) {
            arch::log(&alloc::format!(
                "sigma-kernel: materialize failed {:?}\n",
                e
            ));
            con.println("materialize failed");
            loop {
                arch::halt()
            }
        }
    }

    // Zero the user stack — freshly allocated frames are dirty.
    let st = unsafe {
        core::slice::from_raw_parts_mut(
            img.stack_phys as *mut u8,
            (img.stack_pages * 4096) as usize,
        )
    };
    st.fill(0);
    // /init gets argv[0] = "/init" like any spawned process.
    let init_strings = [b"/init".to_vec()];
    let init_rsp = match unsafe { setup_argv(&img, stack_lo, &init_strings) } {
        Ok(r) => r,
        Err(_) => kernel::process::initial_rsp(&img),
    };

    unsafe {
        USER_PML4 = tables.cr3;
        USER_ALLOC = Some(alloc);
        USER_BRK = 0x10000000;
        // Register /init as process 0 (pid 1, no parent).
        let init_frames =
            (img.segments.iter().map(|s| s.frames).sum::<u64>() + img.stack_pages) as u16;
        PROCS[0] = ProcSlot {
            used: true,
            exited: false,
            sleeping: false,
            wait_pid: 0,
            reaped: false,
            pid: 1,
            parent: -1,
            exit_code: 0,
            pml4: tables.cr3,
            brk: USER_BRK,
            frame_count: init_frames,
            fds: [FdEnt {
                used: false,
                kind: FD_FILE,
                pipe_id: 0,
                path: [0; 64],
                len: 0,
                off: 0,
            }; 8],
        };
        NEXT_PID = 2;
        CUR_PROC = 0;
        cur_ctx = CTX[0].as_mut_ptr() as u64;
        next_ctx = cur_ctx;
        switch_req = 0;
    }
    con.println("entering /init (ring 3)...");
    arch::log("sigma-kernel: entering user mode\n");
    unsafe { enter_user(img.entry, init_rsp, tables.cr3) }
}
